// Q2-M01-v01. Node-centred radial FV, coupled implicit midpoint, BE startup.
// No latent heat. Capacity is B(C) T_t, never d(B(C)T)/dt.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
using V=std::vector<double>;
constexpr double R=.02,H=25.,HM=8e-7;
struct Grid{int n;double dr;V r,w;Grid(int N):n(N),dr(R/N),r(N+1),w(N+1){for(int i=0;i<=n;i++){r[i]=i*dr;double a=i?(i-.5)*dr:0,b=i<n?(i+.5)*dr:R;w[i]=(b*b-a*a)/2;}}};
struct Props{double B,k,D;};
Props props(double c,double T,bool fixed=false){if(!(c>0)||!std::isfinite(c)||!(T+273.15>0))throw std::runtime_error("invalid physical state");if(fixed)return {3e6,.4,5e-9};return {(650+128*c)*(1450+2736*c/(1+c)),.21+.38*c/(1+c),.0024*std::exp(-.45/c-3850/(T+273.15))};}
struct Env{V ts,T,C;Env(const std::string&f){std::ifstream in(f);if(!in)throw std::runtime_error("missing input");std::string s;std::getline(in,s);while(std::getline(in,s)){std::replace(s.begin(),s.end(),',',' ');std::istringstream r(s);double a,b,c;if(r>>a>>b>>c){ts.push_back(a);T.push_back(b);C.push_back(c);}}if(ts.size()<2)throw std::runtime_error("empty input");}double at(const V&v,double t)const{if(t<ts.front()||t>ts.back())throw std::runtime_error("input extrapolation disabled");int i=std::max(0,std::min(int(ts.size())-2,int(std::upper_bound(ts.begin(),ts.end(),t)-ts.begin())-1));double z=(t-ts[i])/(ts[i+1]-ts[i]);return v[i]*(1-z)+v[i+1]*z;}};
double root(double bi){double a=0,b=2.40482555769577;for(int j=0;j<80;j++){double m=(a+b)/2;if(m*::j1(m)-bi*::j0(m)>0)b=m;else a=m;}return (a+b)/2;}
struct Case{std::string mode;Env env;double eT=root(H*R/.4),eC=root(HM*R/5e-9);Case(std::string m,std::string f):mode(m),env(f){}bool fixed()const{return mode=="bessel";}bool exact()const{return mode!="real";}
 void solution(double r,double t,double&T,double&C)const{double x=r/R;if(mode=="mms"){T=28+.4*std::exp(-t/1000)*(1+x*x);C=1+.1*std::exp(-t/700)*(1+x*x);}else if(mode=="bessel"){T=28+.2*::j0(eT*x)*std::exp(-(.4/3e6)*eT*eT*t/(R*R));C=1+.2*::j0(eC*x)*std::exp(-5e-9*eC*eC*t/(R*R));}else{T=28;C=2.55;}}
 void boundary(double t,double&te,double&ce)const{if(mode=="real"){te=env.at(env.T,t);ce=env.at(env.C,t);}else if(mode=="mms"){double T,C;solution(R,t,T,C);auto p=props(C,T);te=T+p.k*2*.4*std::exp(-t/1000)/(R*H);ce=C+p.D*2*.1*std::exp(-t/700)/(R*HM);}else{te=28;ce=mode=="bessel"?1:2.55;}}
 void source(double r,double t,double&ft,double&fc)const{ft=fc=0;if(mode!="mms")return;double x=r/R,a=.4*std::exp(-t/1000),b=.1*std::exp(-t/700),T,C;solution(r,t,T,C);auto p=props(C,T);double kc=.38/((1+C)*(1+C)),dc=.45*p.D/(C*C),dt=3850*p.D/((T+273.15)*(T+273.15));ft=-p.B*a*(1+x*x)/1000-4*a/(R*R)*(p.k+b*x*x*kc);fc=-b*(1+x*x)/700-4*b/(R*R)*(p.D+x*x*(dc*b+dt*a));}
};
struct Workspace{int n;V stageT,stageC,B,k,D,gT,gC,muT,muC,srcT,srcC,diag,upper,rhs,outT,outC;Workspace(int N):n(N),stageT(N+1),stageC(N+1),B(N+1),k(N+1),D(N+1),gT(N),gC(N),muT(N+1),muC(N+1),srcT(N+1),srcC(N+1),diag(N+1),upper(N+1),rhs(N+1),outT(N+1),outC(N+1){}
 void coefficients(const Grid&q,const Case&cs,const V&oldT,const V&oldC,const V&newT,const V&newC,double theta,double dt){for(int i=0;i<=n;i++){stageT[i]=(1-theta)*oldT[i]+theta*newT[i];stageC[i]=(1-theta)*oldC[i]+theta*newC[i];auto p=props(stageC[i],stageT[i],cs.fixed());B[i]=p.B;k[i]=p.k;D[i]=p.D;muT[i]=q.w[i]*p.B/dt;muC[i]=q.w[i]/dt;}for(int i=0;i<n;i++){gT[i]=(i+.5)*(k[i]+k[i+1])/2;gC[i]=(i+.5)*(D[i]+D[i+1])/2;}}
 double flux(const V&g,const V&u,int i,double h,double ext)const{return (i?g[i-1]*(u[i-1]-u[i]):0)+(i<n?g[i]*(u[i+1]-u[i]):R*h*(ext-u[i]));}
 double solve(const V&mu,const V&g,const V&old,const V&src,double theta,double h,double ext,V&out){for(int i=0;i<=n;i++){double left=i?theta*g[i-1]:0,right=i<n?theta*g[i]:0;diag[i]=mu[i]+left+right+(i==n?theta*R*h:0);rhs[i]=mu[i]*old[i]+(1-theta)*flux(g,old,i,h,ext)+theta*(i==n?R*h*ext:0)+src[i];double pivot=diag[i]-(i?left*(-upper[i-1]):0);if(!(pivot>0))throw std::runtime_error("nonpositive pivot");upper[i]=i<n?-right/pivot:0;out[i]=(rhs[i]+(i?left*out[i-1]:0))/pivot;}for(int i=n-1;i>=0;i--)out[i]-=upper[i]*out[i+1];double err=0;for(int i=0;i<=n;i++){double z=diag[i]*out[i]-rhs[i],den=std::abs(rhs[i])+std::abs(diag[i]*out[i]);if(i){z-=theta*g[i-1]*out[i-1];den+=std::abs(theta*g[i-1]*out[i-1]);}if(i<n){z-=theta*g[i]*out[i+1];den+=std::abs(theta*g[i]*out[i+1]);}err=std::max(err,std::abs(z)/(den+1e-300));}return err;}
};
struct SD{int it=0;double resT=0,resC=0,upT=0,upC=0,linear=0;};
bool step(const Grid&q,const Case&cs,Workspace&w,const V&oldT,const V&oldC,V&newT,V&newC,double t,double dt,double theta,double tol,SD&sd){newT=oldT;newC=oldC;double te,ce;cs.boundary(t+theta*dt,te,ce);for(int i=0;i<=q.n;i++){cs.source(q.r[i],t+theta*dt,w.srcT[i],w.srcC[i]);w.srcT[i]*=q.w[i];w.srcC[i]*=q.w[i];}
 for(int it=0;it<=50;it++){w.coefficients(q,cs,oldT,oldC,newT,newC,theta,dt);double rt=0,rc=0,at=0,ac=0;for(int i=0;i<=q.n;i++){double fT=w.muT[i]*(newT[i]-oldT[i])-w.flux(w.gT,w.stageT,i,H,te)-w.srcT[i],fC=w.muC[i]*(newC[i]-oldC[i])-w.flux(w.gC,w.stageC,i,HM,ce)-w.srcC[i];double dT=w.muT[i]+theta*((i?w.gT[i-1]:0)+(i<q.n?w.gT[i]:R*H)),dC=w.muC[i]+theta*((i?w.gC[i-1]:0)+(i<q.n?w.gC[i]:R*HM));rt=std::max(rt,std::abs(fT)/dT);rc=std::max(rc,std::abs(fC)/dC);at=std::max(at,std::abs(newT[i]));ac=std::max(ac,std::abs(newC[i]));}sd.resT=rt;sd.resC=rc;sd.it=it;if(it>0&&sd.upT<=tol*(1+at)&&sd.upC<=tol*(1+ac)&&rt<=tol*(1+at)&&rc<=tol*(1+ac))return true;if(it==50)return false;
 sd.linear=std::max(sd.linear,w.solve(w.muT,w.gT,oldT,w.srcT,theta,H,te,w.outT));sd.linear=std::max(sd.linear,w.solve(w.muC,w.gC,oldC,w.srcC,theta,HM,ce,w.outC));sd.upT=sd.upC=0;for(int i=0;i<=q.n;i++){if(w.outC[i]<=0||!std::isfinite(w.outT[i]))return false;sd.upT=std::max(sd.upT,std::abs(w.outT[i]-newT[i]));sd.upC=std::max(sd.upC,std::abs(w.outC[i]-newC[i]));}newT=w.outT;newC=w.outC;
 }return false;
}
int main(int argc,char**argv){try{if(argc!=11)throw std::runtime_error("solver env prefix N denominator tol mode end budget method schedule");Case cs(argv[6],argv[1]);std::string prefix=argv[2],method=argv[9];int N=std::stoi(argv[3]),schedule=std::stoi(argv[10]);double base=1/std::stod(argv[4]),tol=std::stod(argv[5]),end=std::stod(argv[7]),budget=std::stod(argv[8]);if(N<20||N%20)throw std::runtime_error("N must be a positive multiple of 20");Grid q(N);Workspace w(N);V T(N+1),C(N+1),nt(N+1),nc(N+1);for(int i=0;i<=N;i++)cs.solution(q.r[i],0,T[i],C[i]);double t=0,cap=1e99,minT=T[0],maxT=T[0],minC=C[0],maxC=C[0],resT=0,resC=0,linear=0,errT=0,errC=0,maxbalT=0,maxbalC=0;long long steps=0,iterations=0,rejected=0;int maxit=0;long double balT=0,balC=0,heat=0,water=0;auto start=std::chrono::steady_clock::now();bool completed=true;std::string reason;
 std::ofstream samples(prefix+"_samples.csv"),diagnostics(prefix+"_diagnostics.csv");samples<<std::setprecision(17)<<"time_s";for(auto f:{"T","C"})for(int j=0;j<=20;j++)samples<<","<<f<<"_"<<j;samples<<"\n";diagnostics<<std::setprecision(17)<<"time_s,mean_T,mean_C,steps,iterations,cumulative_heat_per_2piL,cumulative_water_per_rhod_2piL,heat_balance_per_2piL,water_balance_per_rhod_2piL\n";
 auto emit=[&](){samples<<t;for(auto u:{&T,&C})for(int j=0;j<=20;j++)samples<<","<<(*u)[j*N/20];samples<<"\n";long double mt=0,mc=0;for(int i=0;i<=N;i++){mt+=q.w[i]*T[i];mc+=q.w[i]*C[i];if(cs.exact()){double et,ec;cs.solution(q.r[i],t,et,ec);errT=std::max(errT,std::abs(T[i]-et));errC=std::max(errC,std::abs(C[i]-ec));}}diagnostics<<t<<","<<double(mt*2/(R*R))<<","<<double(mc*2/(R*R))<<","<<steps<<","<<iterations<<","<<double(heat)<<","<<double(water)<<","<<double(balT)<<","<<double(balC)<<"\n";};emit();
 while(t<end-1e-12){if(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()>budget){completed=false;reason="wall_budget";break;}double mult=!schedule?1:t<2?1:t<8?4:t<32?16:t<128?64:t<512?128:256;bool startup=steps<2;double theta=(method=="be"||startup)?1:.5;double dt=std::min({startup?base/2:base*mult,cap,end-t,std::floor(t+1e-10)+1-t});if(dt<1e-7){completed=false;reason="minimum_dt";break;}SD sd;if(!step(q,cs,w,T,C,nt,nc,t,dt,theta,tol,sd)){cap=dt/2;rejected++;continue;}
 double te,ce;cs.boundary(t+theta*dt,te,ce);long double zT=0,zC=0,sT=0,sC=0;for(int i=0;i<=N;i++){if(!std::isfinite(nt[i])||!std::isfinite(nc[i])||nc[i]<=0)throw std::runtime_error("invalid accepted state");if(cs.mode=="real"&&(nt[i]<28-1e-7||nt[i]>50.246+1e-7||nc[i]>2.55+1e-8||nc[i]<.01963-1e-8))throw std::runtime_error("physical range violated");zT+=(long double)q.w[i]*w.B[i]*(nt[i]-T[i]);zC+=(long double)q.w[i]*(nc[i]-C[i]);sT+=w.srcT[i];sC+=w.srcC[i];minT=std::min(minT,nt[i]);maxT=std::max(maxT,nt[i]);minC=std::min(minC,nc[i]);maxC=std::max(maxC,nc[i]);}long double Q=(long double)dt*R*H*(te-w.stageT[N]),J=(long double)dt*R*HM*(w.stageC[N]-ce),bT=zT-Q-dt*sT,bC=zC+J-dt*sC;heat+=Q;water+=J;balT+=bT;balC+=bC;maxbalT=std::max(maxbalT,std::abs(double(bT)));maxbalC=std::max(maxbalC,std::abs(double(bC)));T.swap(nt);C.swap(nc);t+=dt;steps++;iterations+=sd.it;maxit=std::max(maxit,sd.it);resT=std::max(resT,sd.resT);resC=std::max(resC,sd.resC);linear=std::max(linear,sd.linear);if(std::abs(t-std::round(t))<1e-10)emit();}
 std::ofstream final(prefix+"_final.csv");final<<std::setprecision(17)<<"r_m,T_C,C_kg_kg\n";for(int i=0;i<=N;i++)final<<q.r[i]<<","<<T[i]<<","<<C[i]<<"\n";
 std::ofstream js(prefix+"_stats.json");js<<std::setprecision(17)<<"{\"completed\":"<<(completed?"true":"false")<<",\"reason\":\""<<reason<<"\",\"mode\":\""<<cs.mode<<"\",\"method\":\""<<method<<"\",\"N\":"<<N<<",\"base_dt\":"<<base<<",\"end_time\":"<<t<<",\"steps\":"<<steps<<",\"rejected\":"<<rejected<<",\"iterations\":"<<iterations<<",\"max_picard\":"<<maxit<<",\"residual_T\":"<<resT<<",\"residual_C\":"<<resC<<",\"linear_backward_error\":"<<linear<<",\"min_T\":"<<minT<<",\"max_T\":"<<maxT<<",\"min_C\":"<<minC<<",\"max_C\":"<<maxC<<",\"max_exact_error_T\":"<<errT<<",\"max_exact_error_C\":"<<errC<<",\"max_heat_balance_per_2piL\":"<<maxbalT<<",\"max_water_balance_per_rhod_2piL\":"<<maxbalC<<",\"cumulative_heat_balance_per_2piL\":"<<double(balT)<<",\"cumulative_water_balance_per_rhod_2piL\":"<<double(balC)<<",\"cumulative_heat_per_2piL\":"<<double(heat)<<",\"cumulative_water_per_rhod_2piL\":"<<double(water)<<",\"wall_seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";
 if(linear>1e-12)throw std::runtime_error("linear residual");return completed?0:3;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
